#!/usr/bin/env bun
async function readStdin(){let chunks=[],decoder=new TextDecoder;for await(let chunk of Bun.stdin.stream())chunks.push(decoder.decode(chunk,{stream:!0}));return chunks.push(decoder.decode()),chunks.join(``)}function writeOutput(output){process.stdout.write(JSON.stringify(output))}const ALLOW_PATTERNS=[/^[a-zA-Z0-9_/.~"'-]/];function isAllowed(command){return ALLOW_PATTERNS.some(function(pattern){return pattern.test(command)})}const SKIP_PATTERNS=[/\b(xxd|hexdump|od|base64|tar|gzip|gunzip|zip|unzip|bzip2|xz|zstd)\b/,/>\s*[^\s|&;]/,/\bfilter\.(mjs|ts)\b/,/&\s*$/,/\b(nohup|setsid)\b/,/\b(docker|podman)\s+(exec|run)\b.*-[a-z]*[it]/,/\bbun\s+build\b/,/\$\(/,/`[^`]+`/,/[<>]\(/,/<<[<-]?\s*\S/,/\b(cd|pushd|popd|export|unset|source)\b/,/^\.\s/,/\beval\b/];function shouldSkip(command){return SKIP_PATTERNS.some(function(pattern){return pattern.test(command)})}const raw=await readStdin(),event=JSON.parse(raw);if(event.tool_name!==`Bash`)writeOutput({});else{let bashInput=event.tool_input;if(!isAllowed(bashInput.command)||shouldSkip(bashInput.command))writeOutput({});else{let filterPath=import.meta.url.endsWith(`.mjs`)?`${import.meta.dir}/filter.mjs`:`${import.meta.dir}/filter.ts`,wrappedCommand=[bashInput.command,` 2>&1 | bun `,filterPath,`; _bof=$PIPESTATUS; (exit "$_bof")`].join(``);writeOutput({hookSpecificOutput:{hookEventName:`PreToolUse`,updatedInput:{...bashInput,command:wrappedCommand}}})}}export{};